import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.DEy3KOfk.js";const m=JSON.parse('{"title":"Java Locator Bar markers","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/waypoints/docs/locator-bar.md"},"headers":[],"relativePath":"packages/waypoints/docs/locator-bar.md","filePath":"packages/waypoints/docs/locator-bar.md","lastUpdated":1791428389000}'),s={name:"packages/waypoints/docs/locator-bar.md"};function c(n,e,i,l,p,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="java-locator-bar-markers" tabindex="-1">Java Locator Bar markers <a class="header-anchor" href="#java-locator-bar-markers" aria-label="Permalink to &quot;Java Locator Bar markers&quot;">​</a></h1><p>New waypoints do not appear in the Locator Bar until their owner enables output. Use <code>/wp locator on &lt;id&gt;</code> to enable it and <code>/wp locator off &lt;id&gt;</code> to remove it. The plugin sends a marker only to Java players who can access the waypoint and are currently in the same dimension.</p><p>Set a marker tint with <code>/wp locator color &lt;id&gt; #RRGGBB</code>; use <code>reset</code> to clear the custom color. An optional Java waypoint-style resource ID can be set with <code>/wp locator java-style &lt;id&gt; &lt;namespace:path&gt;</code>, and cleared with <code>reset</code>. Custom styles require a client resource pack that contains the matching waypoint-style assets.</p><p>Markers are removed when the waypoint is disabled or removed, the player changes dimension, or their access is revoked. The client can also hide Locator Bar markers through its settings, and server rules may disable the feature.</p><p>The plugin targets the pinned Pumpkin API release and has not manually verified vanilla client behavior for custom colors or resource-pack styles. Bedrock output is unsupported because the API does not expose a Bedrock waypoint packet or Locator Bar scripting interface.</p>',5)])])}const u=a(s,[["render",c]]);export{m as __pageData,u as default};
